create table public.studio_projects (id uuid primary key default gen_random_uuid(), user_id uuid not null, name text not null default 'Untitled project', state jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, name));
create table public.creations (id uuid primary key default gen_random_uuid(), user_id uuid not null, client_id bigint not null, prompt text not null, model text not null, kind text not null check (kind in ('image','video')), aspect text not null default '1:1', status text not null default 'pending' check (status in ('pending','done','error')), url text, error text, created_at timestamptz not null default now(), unique (user_id, client_id));
create table public.chat_messages (id uuid primary key default gen_random_uuid(), user_id uuid not null, role text not null check (role in ('u','a')), text text not null, created_at timestamptz not null default now());
create table public.prompt_packs (id uuid primary key default gen_random_uuid(), user_id uuid not null, name text not null, prompt text not null, kind text not null default 'image' check (kind in ('image','video')), created_at timestamptz not null default now());
create table public.storyboards (id uuid primary key default gen_random_uuid(), user_id uuid not null, title text not null default 'Untitled storyboard', concept text not null, reference_urls jsonb not null default '[]'::jsonb, shots jsonb not null default '[]'::jsonb, created_at timestamptz not null default now());
create table public.director_drafts (id uuid primary key default gen_random_uuid(), user_id uuid not null, input text not null, output text not null, model text not null, action text not null default 'treat' check (action in ('treat','film')), created_at timestamptz not null default now());
create table public.capcut_drafts (id uuid primary key default gen_random_uuid(), user_id uuid not null, name text not null, version integer not null, ratio text not null, layers jsonb not null default '[]'::jsonb, duration numeric not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, name, version));
create table public.gallery_items (id uuid primary key default gen_random_uuid(), user_id uuid not null, kind text not null, name text not null, storage_path text not null, prompt text, created_at timestamptz not null default now());
create table public.studio_sessions (id text primary key, user_id uuid not null, name text not null, state jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
grant select, insert, update, delete on public.studio_projects, public.creations, public.chat_messages, public.prompt_packs, public.storyboards, public.director_drafts, public.capcut_drafts, public.gallery_items, public.studio_sessions to authenticated;
grant all on public.studio_projects, public.creations, public.chat_messages, public.prompt_packs, public.storyboards, public.director_drafts, public.capcut_drafts, public.gallery_items, public.studio_sessions to service_role;
do $$ declare t text; begin
foreach t in array array['studio_projects','creations','chat_messages','prompt_packs','storyboards','director_drafts','capcut_drafts','gallery_items','studio_sessions'] loop
execute format('alter table public.%I enable row level security', t);
execute format('create policy "own_%s" on public.%I for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id)', t, t);
end loop; end $$;
create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); return new; end $$;
create trigger touch_studio_projects before update on public.studio_projects for each row execute function public.touch_updated_at();
create policy "own_generations_files" on storage.objects for all to authenticated using (bucket_id = 'generations' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'generations' and (storage.foldername(name))[1] = auth.uid()::text);